// План specs/billing.md 5.1 (#48acac). Pre-Prod, preprod-a (SUB_ROLE), /BillingSubscription, EN. Только чтение (@prod-safe).
// При АКТИВНОЙ подписке на доп. компанию: строка «Extra companies» — Active, $49/month, Monthly и дата следующего списания (не «—»);
// блок «Upcoming billing» — «Extra companies (N)», AMOUNT DUE $49, DUE ON <дата>, без «No upcoming charge is scheduled».
// Факты 17.11 (pp-a после покупки места): Active $49/month Monthly, Next billing Nov 27, 2026; Upcoming «Extra companies (1) $49 due Nov 27, 2026».
// Источник: «מה רצוי» тикета и комментарий программиста. Скриншот: 48acac-upcoming-billing-desktop.png.
// Skip, если доп. компании нет или она «Cancels on» (тогда следующего списания нет — это покрывает extra-companies-cancels-on-date.spec.ts).
// Не сверено с сайтом при записи (только пишется): «AMOUNT DUE»/«DUE ON» — вероятно CSS-верхний регистр, поэтому проверки без учёта регистра.
import { test, expect } from '../../fixtures';
import { SUB_ROLE, openBillingDirect, subscriptionRow } from './billing-helpers';

const DATE = /[A-Z][a-z]{2} \d{1,2}, \d{4}/;

test.describe('Billing — active extra company shows the next charge (#48acac)', () => {
  test('Active extra company: row shows Active, $49/month, Monthly and a date; Upcoming billing shows Extra companies (N), AMOUNT DUE $49, DUE ON date #48acac @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(90_000);
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page, 'en');

    const row = subscriptionRow(page, 'Extra companies');
    test.skip((await row.count()) === 0, 'на аккаунте нет доп. компании — нечего проверять');
    test.skip((await row.getByText(/Cancels on/).count()) > 0, 'доп. компания помечена «Cancels on» — следующего списания нет');

    await expect(row.getByText('Active', { exact: true })).toBeVisible();
    await expect(row.getByText('$49')).toBeVisible();
    await expect(row.getByText('/month')).toBeVisible();
    await expect(row.getByText('Monthly', { exact: true })).toBeVisible();
    await expect(row, 'в строке есть дата следующего списания, не «—»').toContainText(DATE);
    const rowDate = DATE.exec((await row.innerText()) ?? '')?.[0];
    expect(rowDate).toBeTruthy();

    const upcoming = page.getByText('Upcoming billing', { exact: true }).locator('xpath=ancestor::*[self::section or self::div][2]');
    await expect(upcoming.getByText(/Extra companies \(\d+\)/)).toBeVisible();
    await expect(upcoming).toContainText(/amount due/i);
    await expect(upcoming).toContainText('$49');
    await expect(upcoming).toContainText(new RegExp(`due on\\s*${rowDate}`, 'i'));
    await expect(upcoming.getByText('No upcoming charge is scheduled.')).toHaveCount(0);
  });
});
